; ============================================================
; Chrono Trigger (SNES): the whole ROM, as `make build` assembles it
;
; asm/main.asm is the code source (65816, the SPC700 driver, the packed
; $C3 module); asm/data/ is the data layer, generated by
; tools/extract_data.py from symbols/data_survey.csv, which places
; every byte the code source does not emit. tools/build_rom.py
; assembles this file onto a blank 4 MB image (twice, $00 and $FF, and
; requires both to agree: every byte is written); nothing is copied
; from the original ROM. The tools that measure the code source
; (tools/verify.py, tools/progress.py) assemble asm/main.asm alone.
; ============================================================

incsrc "main.asm"
incsrc "data/data.asm"
